/*
 * The Good Stuff DS runtime: draws whatever `gs_scene` (source/scene_data.c, generated by the compiler) describes and runs the scripts
 * in source/script_code.c (also generated). There is deliberately no game logic here — no node kinds beyond what drawing needs. If the
 * runtime needs to know something, the data says it.
 *
 * Requirements: requirements/compiler/TASK.ds-runtime-c-template.md, TASK.runtime-node-table-and-script-services.md
 */
#include <nds.h>
#include <filesystem.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "gs_api.h"
#include "gs_runtime.h"
#include "scene.h"

/* Material colors shared by every mesh until the scene model has materials. */
#define AMBIENT_COLOR RGB15(8, 8, 8)

/* A smooth-skinned mesh instance blends up to this many distinct bones. Extra joints past this are silently dropped
   (their weight is simply not applied) -- a real, confirmed failure mode, not a hypothetical one: a whole-character
   `unifiedSkinning` mesh (one mesh for the entire rig, by that path's own design -- see translate-scene-3d.ts's own
   comment) referenced 22 distinct bones on a real file, and the 16-bone version of this limit silently dropped
   everything from the knee down on both legs, rendering as visibly short legs with no error or warning anywhere.
   `translate-scene-3d.ts`'s own `MAX_SKIN_JOINTS_PER_MESH` constant mirrors this value and warns at compile time
   when a mesh would exceed it -- keep the two in sync if this is ever changed. 32 comfortably covers a normal
   Mixamo-style body rig (spine, arms, legs, no separately-rigged fingers) with headroom; a richly-rigged mesh (full
   finger bones, etc.) can still exceed it, which is exactly what the compiler warning is for. */
#define GS_MAX_SKIN_JOINTS_PER_MESH 32

/* `out = a * b`, both column-major 4x4 affine (20.12) matrices -- the one general 4x4 multiply this runtime needs
   (compose_node's own node-to-node composition keeps rotation and scale apart on purpose; see its own comment in
   gs_runtime.c). Both `a` and `b`'s own bottom row is assumed to be the implicit affine [0, 0, 0, 1]. */
static void mat4_multiply(const int32_t *a, const int32_t *b, int32_t *out) {
	for (int col = 0; col < 4; col++) {
		for (int row = 0; row < 3; row++) {
			int64_t sum = col == 3 ? (int64_t)a[12 + row] << 12 : 0; /* a's own translation, only for b's translation column (b's implicit w = 1 there) */
			for (int k = 0; k < 3; k++) sum += (int64_t)a[k * 4 + row] * b[col * 4 + k];
			out[col * 4 + row] = (int32_t)(sum >> 12);
		}
	}
	out[3] = out[7] = out[11] = 0;
	out[15] = GS_ONE;
}

/* The 3D backdrop. Not black, so screenshots can find the screen (tests read this value). */
#define CLEAR_R 3
#define CLEAR_G 5
#define CLEAR_B 10

/* ---- Drawing ---------------------------------------------------------------------------------------------------------------------- */

/* The texture names glGenTextures gave each of gs_scene.textures, in order. */
static int *textureNames;

/* The camera's view this frame (load_view, below), kept around rather than just loaded straight to the GPU:
   draw_skinned_mesh's own glLoadMatrix4x4 calls -- one per vertex, replacing MODELVIEW outright instead of building
   on whatever glPushMatrix saved -- need it folded back in by hand; see that function's own comment. */
static GsMatrix gs_current_view;

/* draw_skinned_mesh's own (view * world * invBind) blend, one packed 4x3 matrix per node, cached for the rest of the
   current frame: a rigged character is normally several meshes (head, torso, arms, legs, ...) all skinned to the
   same one skeleton, so the same bone is a joint of more than one of them, and recomputing its blend from scratch
   for every mesh that references it -- the same cost gs_runtime.c's own ComposeMemo exists to avoid for plain node
   composition -- wastes real work once a scene has more than one smooth-skinned mesh sharing a bone (exactly the
   "3-5-8 skinned characters" case this matters for). Sized to the scene's own node count and allocated alongside
   gs_world_matrix in enter_scene; gs_skin_blend_frame[node] holds which frame number last computed that node's
   entry, so a stale one (an old frame, or never computed) is detected by a single integer compare. */
static int32_t (*gs_skin_blend_cache)[12];
static uint16_t *gs_skin_blend_frame;
static uint16_t gs_frame_number;
/* What invBindMatrix the cached entry above was actually computed from, so a cache "hit" is only trusted once its
   source is confirmed identical -- never just assumed from the node matching. Two meshes sharing a bone normally do
   share the exact same inverse-bind values (one skeleton has one bind pose, regardless of how many meshes are
   skinned to it), but the compiler currently writes each mesh's own copy into gs_scene.skinInverseBindMatrices
   rather than one shared entry, so the values must be compared, not just assumed equal from the node index alone --
   this is what keeps the cache correct even if that compiler-side assumption is ever wrong for some mesh. */
static int32_t (*gs_skin_blend_source)[16];

/* Uploads every texture to texture memory once, at startup. */
static void load_textures(void) {
	if (gs_scene.textureCount == 0) return;
	textureNames = malloc(sizeof(int) * gs_scene.textureCount);
	glGenTextures(gs_scene.textureCount, textureNames);
	for (int i = 0; i < gs_scene.textureCount; i++) {
		const GsTexture *texture = &gs_scene.textures[i];
		glBindTexture(0, textureNames[i]);
		/* sizeS/sizeT are the DS's size classes (TEXTURE_SIZE_8 is 0 ... TEXTURE_SIZE_1024 is 7). Wrapping is on, so a coordinate past the edge tiles the picture. */
		glTexImage2D(0, 0, GL_RGBA, texture->sizeS, texture->sizeT, 0,
			TEXGEN_TEXCOORD | GL_TEXTURE_WRAP_S | GL_TEXTURE_WRAP_T, texture->texels);
	}
}

/* Draws a smooth-skinned mesh (MeshInstance3DData.smoothSkinning): a weighted blend of up to
   GS_MAX_SKIN_JOINTS_PER_MESH bones' own current world transforms, recomputed whenever a vertex's own joint/weight
   signature differs from the previous vertex's (nsbmd_docs.txt's own "Calculate Skinning Equation" -- the same
   technique real DS games with smooth joints use; MKDS itself draws this way, which is exactly how it affords doing
   it at 60 fps). The GPU still only ever has one "current" matrix, so a mesh with more than one distinct blend
   across it needs more than one matrix load -- real CPU and GX FIFO cost, which is why it's opt-in rather than the
   default (see draw_mesh's own rigid path) -- but three things keep that cost down to roughly what the rigid path
   already pays for an ordinary mesh: (1) consecutive vertices sharing one signature (most of any real mesh, away
   from a joint seam, where one bone carries full weight for a long run of vertices) skip the blend and the matrix
   load entirely, reusing whatever's already loaded; (2) a vertex weighted entirely to one bone skips the weighted
   sum and loads that bone's own matrix directly, the same single load the rigid path would do; (3) see the per-term
   comment below on replacing a 32-bit divide (ARM9 has no hardware divide; every one is tens of cycles through
   libgcc) with a multiply and a shift. Only a vertex that's a genuine multi-bone blend, immediately after a
   different one, pays the full per-vertex cost this function was written to afford in the first place. Each joint's
   own world scale is folded in and used for *both* the position and the normal transform (unlike the rigid path's
   own position-only scale, which keeps a uniformly-scaled mesh's lighting correct) -- an approximation that's exact
   whenever a bone's own scale is 1, which every bone in a real character rig's skeleton normally is.

   Every glLoadMatrix4x4 below *replaces* MODELVIEW rather than building on it, so draw_mesh's own glPushMatrix (which
   saved the camera's view) never actually reaches the GPU for this mesh unless it's folded back in here by hand --
   each joint's blend term gets the view matrix premultiplied in once, up front (view * (world * invBind), the same
   for every vertex that bone influences), instead of once per vertex: matrix multiplication distributes over the
   weighted sum, so premultiplying each joint and then blending gives an identical result to blending first and
   multiplying by view after, for no extra per-vertex cost. Without this, a mesh at or near its bind pose blends to
   very close to the identity matrix, which would put its vertices in raw local space instead of view space --
   invisible (off-frustum) unless the camera's own view happens to be close enough to identity that neither is
   distinguishable from the other, which is exactly what masked this for a single mesh in earlier testing. */
static void draw_skinned_mesh(const GsMesh *mesh, const GsPrimitive *primitive) {
	int jointCount = mesh->skinJointCount;
	if (jointCount > GS_MAX_SKIN_JOINTS_PER_MESH) jointCount = GS_MAX_SKIN_JOINTS_PER_MESH;
	/* Packed 4x3 (column-major, 3 rows per column -- the m4x3 layout glLoadMatrix4x3/MATRIX_LOAD4x3 expects,
	   confirmed against a known-good render rather than guessed), not the full 4x4: every
	   affine matrix's own implicit bottom row (0, 0, 0, 1) is the same for all of them, so there's no reason to
	   store it, blend it, or send it to the GPU 16 words at a time when 12 will do -- a quarter less FIFO traffic
	   for every matrix load below, and a quarter less per-vertex multiply-accumulate work in the blend loop. */
	int32_t jointMatrix[GS_MAX_SKIN_JOINTS_PER_MESH][12];
	for (int j = 0; j < jointCount; j++) {
		int node = gs_scene.skinJoints[mesh->skinJointStart + j];
		const int32_t *invBind = gs_scene.skinInverseBindMatrices[mesh->skinJointStart + j].m;
		/* A cache hit needs both this frame's number AND this exact invBindMatrix (see gs_skin_blend_source's own
		   comment) -- the node index alone isn't enough to trust a value another mesh computed earlier this frame. */
		if (gs_skin_blend_frame[node] != gs_frame_number || memcmp(gs_skin_blend_source[node], invBind, sizeof(int32_t[16])) != 0) {
			int32_t worldWithScale[16];
			memcpy(worldWithScale, gs_world_matrix[node].m, sizeof(worldWithScale));
			for (int col = 0; col < 3; col++) {
				int32_t s = gs_world_scale[node][col];
				for (int row = 0; row < 3; row++) worldWithScale[col * 4 + row] = gs_mulf(worldWithScale[col * 4 + row], s);
			}
			int32_t boneWithBind[16];
			mat4_multiply(worldWithScale, invBind, boneWithBind);
			int32_t full[16];
			mat4_multiply(gs_current_view.m, boneWithBind, full);
			for (int col = 0; col < 4; col++)
				for (int row = 0; row < 3; row++) gs_skin_blend_cache[node][col * 3 + row] = full[col * 4 + row];
			memcpy(gs_skin_blend_source[node], invBind, sizeof(int32_t[16]));
			gs_skin_blend_frame[node] = gs_frame_number;
		}
		memcpy(jointMatrix[j], gs_skin_blend_cache[node], sizeof(jointMatrix[j]));
	}

	const int16_t *p = primitive->positions;
	const uint32_t *n = primitive->normals;
	const int16_t *uv = mesh->texture ? primitive->texcoords : 0;
	const uint8_t *vj = primitive->skinJoints;
	const uint8_t *vw = primitive->skinWeights;
	int vertexCount = primitive->triangleCount * 3;

	glMatrixMode(GL_MODELVIEW);
	glBegin(GL_TRIANGLES);
	/* An impossible joint/weight signature, so the very first vertex always computes and loads its own matrix. */
	int lastJ[4] = { -1, -1, -1, -1 };
	int lastW[4] = { -1, -1, -1, -1 };
	for (int i = 0; i < vertexCount; i++) {
		const uint8_t *j4 = &vj[i * 4];
		const uint8_t *w4 = &vw[i * 4];
		/* ARM9 has no hardware divide (every `/` or `%` on it is a software call, tens of cycles vs. one or two for a
		   multiply), and a real mesh reuses the same handful of joint/weight combinations across most of its
		   vertices (an entire flat region away from a joint seam is typically one bone at full weight, repeated).
		   Skipping both the blend math and the matrix reload whenever this vertex's signature matches the previous
		   one's turns most meshes' per-vertex cost into a handful of reads and a compare, not 4 joints' worth of
		   multiply-accumulate plus a GX FIFO matrix load every time. */
		if (j4[0] != lastJ[0] || j4[1] != lastJ[1] || j4[2] != lastJ[2] || j4[3] != lastJ[3] ||
			w4[0] != lastW[0] || w4[1] != lastW[1] || w4[2] != lastW[2] || w4[3] != lastW[3]) {
			if (w4[0] == 255 && w4[1] == 0 && w4[2] == 0 && w4[3] == 0 && j4[0] < jointCount) {
				/* The common case away from a joint seam: one bone at full weight, same as the rigid path would draw
				   it -- no blend to compute at all, just load that bone's own already-blended (view * world *
				   invBind) matrix. */
				glLoadMatrix4x3((const m4x3 *)jointMatrix[j4[0]]);
			} else {
				int32_t blended[12] = { 0 };
				for (int k = 0; k < 4; k++) {
					int w = w4[k];
					if (w == 0) continue;
					int jt = j4[k];
					if (jt >= jointCount) continue;
					/* `x / 255` as `(x * 257) >> 16` -- 257/65536 is within 1 part in 65536 of 1/255, far finer than
					   this 20.12 fixed point already resolves, and replaces a 32-bit divide with a multiply and a
					   shift. The int64_t keeps a large translation component times 255*257 from overflowing. */
					int w257 = w * 257;
					const int32_t *jm = jointMatrix[jt];
					for (int e = 0; e < 12; e++) blended[e] += (int32_t)(((int64_t)jm[e] * w257) >> 16);
				}
				glLoadMatrix4x3((const m4x3 *)blended);
			}
			lastJ[0] = j4[0]; lastJ[1] = j4[1]; lastJ[2] = j4[2]; lastJ[3] = j4[3];
			lastW[0] = w4[0]; lastW[1] = w4[1]; lastW[2] = w4[2]; lastW[3] = w4[3];
		}
		if (uv) glTexCoord2t16(uv[i * 2], uv[i * 2 + 1]);
		glNormal(n[i]);
		glVertex3v16(p[i * 3], p[i * 3 + 1], p[i * 3 + 2]);
	}
	glEnd();
}

static void draw_mesh(const GsMesh *mesh, int index, int lit) {
	const GsPrimitive *primitive = &gs_scene.primitives[gs_mesh_primitive(index)];
	const int16_t *uv = mesh->texture ? primitive->texcoords : 0;

	/* Binding texture 0 turns texturing off for the polygons that follow. */
	glBindTexture(0, uv ? textureNames[mesh->texture - 1] : 0);

	glMaterialf(GL_AMBIENT, AMBIENT_COLOR);
	glMaterialf(GL_DIFFUSE, mesh->diffuse);
	glMaterialf(GL_SPECULAR, RGB15(0, 0, 0));
	/* Every glNormal recomputes the vertex color as emission + the enabled lights' contributions, so with no lights the color is just the
	   emission, and that is what an unlit mesh shows: its own color, full brightness. (With emission left at black, a scene with no
	   light drew pure black.) */
	glMaterialf(GL_EMISSION, lit ? RGB15(0, 0, 0) : mesh->diffuse);

	glPushMatrix();
	if (mesh->skinJointCount > 0) {
		draw_skinned_mesh(mesh, primitive);
	} else {
		const int16_t *p = primitive->positions;
		const uint32_t *n = primitive->normals;
		int vertexCount = primitive->triangleCount * 3;
		/* Rotation and translation go to the position matrix AND the vector (normal) matrix. Scale is applied to the
		   position matrix alone: the geometry engine transforms a normal by the same matrix as a position and never
		   renormalizes it, so scale left in the vector matrix would lengthen or shorten every normal and wreck the
		   lighting (a mesh scaled 3x got no light at all). */
		glMultMatrix4x4((const m4x4 *)&gs_world_matrix[mesh->node]);
		glMatrixMode(GL_POSITION);
		glScalef32(gs_world_scale[mesh->node][0], gs_world_scale[mesh->node][1], gs_world_scale[mesh->node][2]);
		glMatrixMode(GL_MODELVIEW);

		glBegin(GL_TRIANGLES);
		for (int i = 0; i < vertexCount; i++) {
			if (uv) glTexCoord2t16(uv[i * 2], uv[i * 2 + 1]);
			glNormal(n[i]);
			glVertex3v16(p[i * 3], p[i * 3 + 1], p[i * 3 + 2]);
		}
		glEnd();
	}
	glPopMatrix(1);
}

/* The camera's view, as the scene starts or as a script has moved it. */
static void load_view(void) {
	gs_compute_view(&gs_current_view);
	glLoadMatrix4x4((const m4x4 *)&gs_current_view);
}

/* Draws the scene's SkyBox3D, if it has one, as a full-screen two-triangle gradient (STORY.sky-box.md) -- the DS has
   no hardware gradient clear, so this takes glClearColor's own place for a scene that has one: skyBoxTopColor at the
   top edge of the screen, blending down into skyBoxHorizonColor at the bottom (the geometry engine interpolates a
   triangle's own per-vertex color across it for free; no texture or lighting needed). Identity modelview (it never
   turns with the camera, same as a fixed screen backdrop) but the scene's own real projection, so it fills the
   screen exactly like any mesh at that same distance would. Drawn with alpha one step under fully opaque so the DS
   skips writing its own depth entirely (the same rule a translucent mesh already relies on -- see draw_mesh's own
   comment on GsMesh.alpha): every real polygon drawn after it this frame still depth-tests against the untouched,
   just-cleared depth buffer, so it draws over the sky box correctly regardless of where in the world it actually
   is. That means this has to run before any real geometry this frame, and it has to be a drawn polygon redone every
   single frame, not a one-time setup: the framebuffer isn't preserved from one frame to the next on the DS. */
static void draw_sky_box(void) {
	if (!gs_scene.hasSkyBox) return;
	glMatrixMode(GL_MODELVIEW);
	glLoadIdentity();
	glBindTexture(0, 0);
	glPolyFmt(POLY_ALPHA(30) | POLY_CULL_NONE);

	/* gs_scene.skyBoxDistance (set from SkyBox3D's own Inspector slider, STORY.sky-box.md) is clamped at compile
	   time to stay comfortably inside a vertex's own v16 (4.12 fixed point) +-8 unit range -- how far away it
	   actually sits doesn't matter for draw order (see above) or for how much of the screen it fills (halfHeight/
	   halfWidth below scale with it), only that it's further than any sane near plane. */
	const float z = -gs_scene.skyBoxDistance;
	const float halfHeight = gs_scene.tanHalfFov * -z;
	const float halfWidth = halfHeight * (256.0f / 192.0f);
	const int16_t zv = (int16_t)(z * 4096.0f);
	const int16_t top = (int16_t)(halfHeight * 4096.0f);
	const int16_t bottom = (int16_t)(-halfHeight * 4096.0f);
	const int16_t left = (int16_t)(-halfWidth * 4096.0f);
	const int16_t right = (int16_t)(halfWidth * 4096.0f);

	glBegin(GL_TRIANGLES);
	glColor(gs_scene.skyBoxTopColor);
	glVertex3v16(left, top, zv);
	glColor(gs_scene.skyBoxHorizonColor);
	glVertex3v16(left, bottom, zv);
	glVertex3v16(right, bottom, zv);
	glColor(gs_scene.skyBoxTopColor);
	glVertex3v16(left, top, zv);
	glColor(gs_scene.skyBoxHorizonColor);
	glVertex3v16(right, bottom, zv);
	glColor(gs_scene.skyBoxTopColor);
	glVertex3v16(right, top, zv);
	glEnd();
}

/* ---- TileMap3D: chunks streamed from the ROM's own NitroFS region, not resident all at once (STORY.tile-map-3d.md's Phase 3) -------- */

/* Must match TILE_MAP_3D_CHUNK_SIZE (packages/core/src/tile-map-3d.ts) and translate-tile-map-3d.ts's own chunk file
   format: CHUNK_SIZE^3 cells, 2 bytes each (palette index + 1, 0 = empty; then rotationY), indexed lx + ly*8 + lz*64. */
#define TM3D_CHUNK_SIZE 8
#define TM3D_CELLS_PER_CHUNK (TM3D_CHUNK_SIZE * TM3D_CHUNK_SIZE * TM3D_CHUNK_SIZE)
#define TM3D_CHUNK_BYTES (TM3D_CELLS_PER_CHUNK * 2)
/* A 3x3x3 window of loaded chunks around the camera (24 scene units to a side, at the default chunk size) --
   proves the point of streaming (a painted world far larger than this is never resident at once) without needing
   many chunks loaded just to avoid visible pop-in as the camera moves. */
#define TM3D_WINDOW 3
#define TM3D_SLOTS (TM3D_WINDOW * TM3D_WINDOW * TM3D_WINDOW)

typedef struct {
	int valid; /* this slot's (cx, cy, cz) is the most recent load attempt for that position, and `cells` reflects it exactly -- either real chunk data, or all zero (an empty chunk, same as one with no file: translate-tile-map-3d.ts never writes an empty chunk's file at all) */
	int cx, cy, cz;
	uint8_t cells[TM3D_CHUNK_BYTES];
} Tm3dSlot;

/* One fixed pool of TM3D_SLOTS slots per TileMap3D node in the scene, flat (tm3d_slots[tileMapIndex * TM3D_SLOTS + slot]) --
   allocated in enter_scene alongside every other per-scene table, freed and rebuilt the same way. tm3d_center is the
   chunk each pool was last centred on; tm3d_has_center says whether that's happened yet (so the very first frame
   always loads, rather than comparing against a stale all-zero center that might legitimately be (0,0,0)). */
static Tm3dSlot *tm3d_slots;
static int *tm3d_center; /* 3 ints (cx, cy, cz) per TileMap3D node, flat */
static uint8_t *tm3d_has_center;
/* Reused scratch space for whichever TileMap3D tm3d_refresh is currently recentring (one at a time, never concurrently)
   -- TM3D_SLOTS Tm3dSlot structures is tens of KB, too large to put on the ARM9's own small stack. */
static Tm3dSlot *tm3d_scratch;

static void tm3d_free_tables(void) {
	free(tm3d_slots);
	free(tm3d_center);
	free(tm3d_has_center);
	free(tm3d_scratch);
	tm3d_slots = 0;
	tm3d_center = 0;
	tm3d_has_center = 0;
	tm3d_scratch = 0;
}

static void tm3d_init(void) {
	tm3d_free_tables();
	if (gs_scene.tileMap3DCount == 0) return;
	tm3d_slots = malloc(sizeof(Tm3dSlot) * TM3D_SLOTS * gs_scene.tileMap3DCount);
	tm3d_center = malloc(sizeof(int) * 3 * gs_scene.tileMap3DCount);
	tm3d_has_center = calloc(gs_scene.tileMap3DCount, 1);
	tm3d_scratch = malloc(sizeof(Tm3dSlot) * TM3D_SLOTS);
	for (int i = 0; i < TM3D_SLOTS * gs_scene.tileMap3DCount; i++) tm3d_slots[i].valid = 0;
}

/* `worldPos` (f32, world space) expressed in TileMap3D node `node`'s own local space: the inverse of compose_node's
   own rotation + scale + translation (gs_runtime.c) -- the same way gs_compute_view inverts a camera's rotation and
   translation, with scale (ignored for a camera, but not for a grid: scaling a TileMap3D scales its cell spacing
   too) divided back out afterward. Used only to decide which chunk is nearest the camera, an occasional calculation,
   not a per-vertex one. */
static void tm3d_world_to_local(int node, const int32_t worldPos[3], int32_t out[3]) {
	const int32_t *w = gs_world_matrix[node].m;
	int32_t rel[3];
	for (int row = 0; row < 3; row++) rel[row] = worldPos[row] - w[12 + row];
	for (int row = 0; row < 3; row++) {
		int64_t sum = 0;
		for (int k = 0; k < 3; k++) sum += (int64_t)w[row * 4 + k] * rel[k]; /* row of R^T == row of R read across, not down -- see gs_compute_view's own comment */
		out[row] = gs_divf((int32_t)(sum >> 12), gs_world_scale[node][row]);
	}
}

/* Loads chunk (cx, cy, cz) of `tileMap` into `slot`, or leaves it all zero (an empty chunk) when that chunk has no
   file at all -- translate-tile-map-3d.ts never writes one for a chunk with no painted cells, so a missing file is
   the ordinary, expected case for most of a sparse world, not an error. */
static void tm3d_load(const GsTileMap3D *tileMap, int cx, int cy, int cz, Tm3dSlot *slot) {
	slot->valid = 1;
	slot->cx = cx;
	slot->cy = cy;
	slot->cz = cz;
	memset(slot->cells, 0, sizeof(slot->cells));
	char path[96];
	snprintf(path, sizeof(path), "nitro:/%s%d_%d_%d.bin", tileMap->chunkPathPrefix, cx, cy, cz);
	FILE *f = fopen(path, "rb");
	if (!f) return;
	fread(slot->cells, 1, TM3D_CHUNK_BYTES, f);
	fclose(f);
}

/* Recentres TileMap3D `t`'s own window of loaded chunks on wherever the camera now is, if it has crossed into a
   different chunk since the last time this ran (the common case, most frames: nothing to do, one integer compare
   per axis). A slot already holding the right chunk is kept as-is rather than reloaded -- sliding the window by one
   chunk, the ordinary case of the camera walking through the world, reuses most of it. */
static void tm3d_refresh(int t, const GsTileMap3D *tileMap, const int32_t cameraWorld[3]) {
	int32_t local[3];
	tm3d_world_to_local(tileMap->node, cameraWorld, local);
	/* Floor to the containing cell (f32 -> int, arithmetic shift so a negative position floors correctly, same
	   convention this runtime already relies on elsewhere -- see mat4_multiply's own `>> 12`), then floor-divide by
	   TM3D_CHUNK_SIZE (a power of two: another arithmetic shift) to the chunk it's in -- chunkOf's own math in
	   packages/core/src/tile-map-3d.ts, just done in fixed point instead of on a stored integer cell coordinate. */
	int cx = (local[0] >> 12) >> 3, cy = (local[1] >> 12) >> 3, cz = (local[2] >> 12) >> 3;

	int *center = &tm3d_center[t * 3];
	if (tm3d_has_center[t] && center[0] == cx && center[1] == cy && center[2] == cz) return;

	Tm3dSlot *slots = &tm3d_slots[t * TM3D_SLOTS];
	const int half = TM3D_WINDOW / 2;
	int n = 0;
	for (int dz = -half; dz <= half; dz++) {
		for (int dy = -half; dy <= half; dy++) {
			for (int dx = -half; dx <= half; dx++) {
				int wx = cx + dx, wy = cy + dy, wz = cz + dz;
				int found = -1;
				for (int i = 0; i < TM3D_SLOTS; i++) {
					if (slots[i].valid && slots[i].cx == wx && slots[i].cy == wy && slots[i].cz == wz) {
						found = i;
						break;
					}
				}
				if (found >= 0) tm3d_scratch[n] = slots[found];
				else tm3d_load(tileMap, wx, wy, wz, &tm3d_scratch[n]);
				n++;
			}
		}
	}
	memcpy(slots, tm3d_scratch, sizeof(Tm3dSlot) * TM3D_SLOTS);
	center[0] = cx;
	center[1] = cy;
	center[2] = cz;
	tm3d_has_center[t] = 1;
}

/* Draws every non-empty cell of TileMap3D `t`'s own currently-loaded window: the grid's own world transform once
   (its node's rotation/translation via glMultMatrix4x4, same as draw_mesh's own rigid path, then its scale on the
   position matrix alone, for the same lighting reason draw_mesh's own comment gives), then each painted cell's own
   translation and Y-axis yaw on top of that, same convention compose_node itself uses for a pure-Y rotation. */
static void tm3d_draw_node(int t, const GsTileMap3D *tileMap) {
	glPushMatrix();
	glMultMatrix4x4((const m4x4 *)&gs_world_matrix[tileMap->node]);
	glMatrixMode(GL_POSITION);
	glScalef32(gs_world_scale[tileMap->node][0], gs_world_scale[tileMap->node][1], gs_world_scale[tileMap->node][2]);
	glMatrixMode(GL_MODELVIEW);

	Tm3dSlot *slots = &tm3d_slots[t * TM3D_SLOTS];
	for (int s = 0; s < TM3D_SLOTS; s++) {
		const Tm3dSlot *slot = &slots[s];
		if (!slot->valid) continue;
		for (int cellIndex = 0; cellIndex < TM3D_CELLS_PER_CHUNK; cellIndex++) {
			uint8_t raw = slot->cells[cellIndex * 2];
			if (raw == 0) continue; /* unpainted */
			int paletteLocal = raw - 1;
			if (paletteLocal >= tileMap->paletteCount) continue; /* stale data naming a palette entry this scene no longer has -- never crash on it */
			const GsTileMap3DPaletteEntry *entry = &gs_scene.tileMap3DPaletteEntries[tileMap->paletteStart + paletteLocal];
			const GsPrimitive *primitive = &gs_scene.primitives[entry->primitive];
			const uint8_t rotationY = slot->cells[cellIndex * 2 + 1];

			const int lx = cellIndex % TM3D_CHUNK_SIZE;
			const int ly = (cellIndex / TM3D_CHUNK_SIZE) % TM3D_CHUNK_SIZE;
			const int lz = cellIndex / (TM3D_CHUNK_SIZE * TM3D_CHUNK_SIZE);
			const int worldX = slot->cx * TM3D_CHUNK_SIZE + lx;
			const int worldY = slot->cy * TM3D_CHUNK_SIZE + ly;
			const int worldZ = slot->cz * TM3D_CHUNK_SIZE + lz;

			glBindTexture(0, entry->texture ? textureNames[entry->texture - 1] : 0);
			glMaterialf(GL_AMBIENT, AMBIENT_COLOR);
			glMaterialf(GL_DIFFUSE, entry->diffuse);
			glMaterialf(GL_SPECULAR, RGB15(0, 0, 0));
			glMaterialf(GL_EMISSION, RGB15(0, 0, 0)); /* a tile is always lit -- the palette has no per-entry unlit flag (yet) */

			const int32_t cb = gs_cos(gs_i2f(rotationY * 90)), sb = gs_sin(gs_i2f(rotationY * 90));
			int32_t cellMatrix[16] = {
				cb, 0, -sb, 0,
				0, GS_ONE, 0, 0,
				sb, 0, cb, 0,
				gs_i2f(worldX), gs_i2f(worldY), gs_i2f(worldZ), GS_ONE
			};
			glPushMatrix();
			glMultMatrix4x4((const m4x4 *)cellMatrix);

			const int16_t *p = primitive->positions;
			const uint32_t *n = primitive->normals;
			const int16_t *uv = entry->texture ? primitive->texcoords : 0;
			const int vertexCount = primitive->triangleCount * 3;
			glBegin(GL_TRIANGLES);
			for (int i = 0; i < vertexCount; i++) {
				if (uv) glTexCoord2t16(uv[i * 2], uv[i * 2 + 1]);
				glNormal(n[i]);
				glVertex3v16(p[i * 3], p[i * 3 + 1], p[i * 3 + 2]);
			}
			glEnd();
			glPopMatrix(1);
		}
	}
	glPopMatrix(1);
}

/* Every TileMap3D in the scene: recentres each one's own streamed window on the camera, then draws whatever's
   loaded. Always opaque (the palette has no per-entry alpha yet), so this runs once, before the mesh loop's own
   opaque pass -- a translucent mesh drawn afterward then still sorts against it correctly. */
static void draw_tile_maps_3d(uint32_t litBits) {
	if (gs_scene.tileMap3DCount == 0) return;
	const int32_t *cw = gs_world_matrix[gs_scene.cameraNode].m;
	const int32_t cameraWorld[3] = { cw[12], cw[13], cw[14] };
	glPolyFmt(POLY_ALPHA(31) | POLY_ID(0) | POLY_CULL_NONE | litBits);
	for (int t = 0; t < gs_scene.tileMap3DCount; t++) {
		const GsTileMap3D *tileMap = &gs_scene.tileMaps3D[t];
		if (!gs_world_visible[tileMap->node]) continue;
		tm3d_refresh(t, tileMap, cameraWorld);
		tm3d_draw_node(t, tileMap);
	}
}

/* The scripts of the scene being shown. */
static const GsScriptInstance *scriptInstances;
static uint16_t scriptCount;

/*
 * Shows scene `index` of the project (the starting scene is 0): the screen the 3D is on, the VRAM banks, the camera's lens, the textures, every table the runtime keeps for a scene, the
 * scripts' starting values and their `_ready`. `first` is the start of the game; otherwise the scene being shown is put away first (its sounds stopped, its memory given back, its
 * textures and sprites cleared).
 */
static void enter_scene(int index, int first) {
	if (!first) {
		gs_leave_scene();
		glResetTextures();
	}
	gs_scene_current = gs_scene_table[index];

	/* The DS can only drive 3D on one screen; the scene says which. */
	if (gs_scene.screen == 0) {
		lcdMainOnTop();
	} else {
		lcdMainOnBottom();
	}

	videoSetMode(MODE_0_3D);
	videoSetModeSub(MODE_0_2D); /* the other screen stays a plain backdrop */
	setBackdropColorSub(RGB15(0, 0, 0));

	/* All four VRAM banks are texture memory: 512 KB, which is the budget the compiler checks against. */
	vramSetBankA(VRAM_A_TEXTURE);
	vramSetBankB(VRAM_B_TEXTURE);
	vramSetBankC(VRAM_C_TEXTURE);
	/* ... unless the 2D screen has sprites: the sub engine's sprite tiles need a bank of their own (D), and textures keep A to C (384 KB, which is the budget the
	   compiler checks against in that case). */
	if (gs_scene.sprites2D.spriteCount > 0) {
		vramSetBankD(VRAM_D_SUB_SPRITE);
	} else {
		vramSetBankD(VRAM_D_TEXTURE);
	}
	/* Text on the 2D screen is a background of the sub engine, in bank H (32 KB, otherwise unused). */
	if (gs_scene.sprites2D.labelCount > 0) vramSetBankH(VRAM_H_SUB_BG);

	if (first) {
		/* Mounts the ROM's own NitroFS region (STORY.tile-map-3d.md) -- always, even for a project with none of its
		   own files in it, so "nitro:/..." paths just fail an fopen() harmlessly instead of needing a feature flag.
		   Standard devkitPro stdio (fopen/fread/fclose) works on it unchanged once this has run. */
		nitroFSInit(NULL);
		glInit();
		glEnable(GL_TEXTURE_2D);
		glClearColor(CLEAR_R, CLEAR_G, CLEAR_B, 31); /* opaque: a visible backdrop, so a picture of the screen shows where its edges are */
		glClearPolyID(63);
		glClearDepth(0x7FFF);
		glViewport(0, 0, 255, 191);
	}
	/* GL_BLEND (DISP3DCNT bit 3) is a global geometry-engine switch, not a per-polygon one: without it the engine
	   stores a polygon's alpha but never blends with it, so every mesh draws fully opaque regardless of
	   GsMesh.alpha. It's only turned on for a scene that actually has a translucent mesh (alpha < 31) or a sky box
	   (draw_sky_box's own polygon is drawn just under fully opaque on purpose, so blending has to be on for that too),
	   not left on for every scene regardless -- a plain, fully-opaque scene has no reason to pay whatever extra
	   per-polygon work the geometry engine does with it on, and each scene is re-checked here since scenes can differ. */
	int translucent = gs_scene.hasSkyBox != 0;
	for (int i = 0; i < gs_scene.meshCount && !translucent; i++) translucent = gs_scene.meshes[i].alpha < 31;
	if (translucent) glEnable(GL_BLEND); else glDisable(GL_BLEND);
	free(textureNames);
	textureNames = 0;
	load_textures();

	glMatrixMode(GL_PROJECTION);
	glLoadIdentity();
	gluPerspective(gs_scene.fovDegrees, 256.0f / 192.0f, gs_scene.nearPlane, gs_scene.farPlane);
	glMatrixMode(GL_MODELVIEW);

	gs_init_nodes();
	free(gs_skin_blend_cache);
	free(gs_skin_blend_frame);
	free(gs_skin_blend_source);
	gs_skin_blend_cache = malloc(sizeof(int32_t[12]) * gs_scene.nodeCount);
	gs_skin_blend_frame = calloc(gs_scene.nodeCount, sizeof(uint16_t));
	gs_skin_blend_source = malloc(sizeof(int32_t[16]) * gs_scene.nodeCount);
	gs_frame_number = 0;
	tm3d_init();
	gs_init_mesh_anim();
	gs_init_touch();
	gs_init_sprites();
	gs_init_labels();
	gs_init_audio();
	gs_start_audio();
	gs_init_animation();
	gs_update_nodes();
	const GsSceneScripts *scripts = &gs_scene_scripts[index];
	scripts->reset();
	scriptInstances = scripts->instances;
	scriptCount = *scripts->count;
	for (int i = 0; i < scriptCount; i++) {
		const GsScriptInstance *script = &scriptInstances[i];
		if (script->ready) script->ready(script->inst);
	}
}

int main(void) {
	enter_scene(0, 1);

	/* 60 fps waits one vertical blank per frame, 30 fps waits two. */
	const int framesPerPresent = gs_scene.fps == 30 ? 2 : 1;
	/* Seconds per frame, as a 20.12 number. */
	const int32_t delta = gs_scene.fps == 30 ? 137 : 68;

	while (pmMainLoop()) {
		gs_frame_number++; /* 0 is "never computed" (gs_skin_blend_frame starts calloc'd to it), so this must run before any draw_skinned_mesh call. */
		gs_read_input();
		gs_update_touch(); /* before the scripts, which ask the touch areas */
		for (int i = 0; i < scriptCount; i++) {
			const GsScriptInstance *script = &scriptInstances[i];
			if (script->process) script->process(script->inst, delta);
		}
		gs_update_mesh_anim();
		gs_update_animation(delta); /* after the scripts: an animation wins over a script that writes the same property */
		gs_update_nodes();

		/* The camera. Lights are set with only the view loaded, because the geometry engine transforms a light's direction by the
		   current matrix when the light is set. */
		load_view();
		/* Before anything else this frame: draw_sky_box's own identity modelview has to be put back to the camera's
		   view before the lights below (and everything after them) runs. */
		draw_sky_box();
		glMatrixMode(GL_MODELVIEW);
		glLoadMatrix4x4((const m4x4 *)&gs_current_view);
		int active = 0;
		for (int i = 0; i < gs_scene.lightCount && active < 4; i++) {
			const GsLight *light = &gs_scene.lights[i];
			if (!gs_world_visible[light->node]) continue;
			int32_t x = light->direction[0], y = light->direction[1], z = light->direction[2];
			if (gs_scene.nodes[light->node].dynamic) {
				/* A light shines along its node's -Z axis: the third column of the rotation, negated, from 20.12 to the v10 fraction. */
				const int32_t *w = gs_world_matrix[light->node].m;
				x = gs_clamp(-w[8] >> 3, -512, 511);
				y = gs_clamp(-w[9] >> 3, -512, 511);
				z = gs_clamp(-w[10] >> 3, -512, 511);
			}
			glLight(active, light->color, x, y, z);
			active++;
		}

		uint32_t litBits = 0;
		for (int i = 0; i < active; i++) litBits |= POLY_FORMAT_LIGHT0 << i;
		/* Always opaque, so drawn once here rather than as part of either pass below -- any translucent mesh in the
		   loop that follows still sorts against it correctly (its depth is already written). */
		draw_tile_maps_3d(litBits);
		/* Each mesh's own cull mode (GS_CULL_NONE/BACK/FRONT, scene.h) -> the geometry engine's own POLY_CULL_* bits. */
		static const uint32_t CULL_BITS[3] = { POLY_CULL_NONE, POLY_CULL_BACK, POLY_CULL_FRONT };
		/* An unlit mesh's polygons carry no light bits at all (not just an emission trick): with a light bit set, the geometry engine would
		   still add that light's diffuse/specular contribution on top of the emission color, brightening it depending on the mesh's own
		   turn relative to the light instead of leaving it at a flat, constant color. */
		/* Opaque meshes draw first, so a translucent one drawn afterward blends with what's already on screen (the DS never
		   writes depth for a polygon below full alpha, so a translucent mesh drawn before an opaque one behind it would let
		   that opaque mesh wrongly draw over it later). Each translucent mesh gets its own poly ID: translucent polygons
		   sharing an ID don't depth-test against each other, which is wanted within one mesh's own triangles (it hides seams
		   instead of self-sorting them) but wrong between two different translucent meshes, which still need to sort. */
		for (int pass = 0; pass < 2; pass++) {
			for (int i = 0; i < gs_scene.meshCount; i++) {
				const GsMesh *mesh = &gs_scene.meshes[i];
				if (!gs_world_visible[mesh->node] || mesh->alpha == 0) continue;
				const int opaque = mesh->alpha >= 31;
				if (opaque != (pass == 0)) continue;
				const uint32_t cull = CULL_BITS[mesh->cull < 3 ? mesh->cull : 0];
				const uint32_t polyId = opaque ? POLY_ID(0) : POLY_ID((i % 63) + 1);
				glPolyFmt(POLY_ALPHA(mesh->alpha) | polyId | cull | (mesh->unlit ? 0 : litBits));
				draw_mesh(mesh, i, !mesh->unlit && active > 0);
			}
		}

		glFlush(0);
		for (int i = 0; i < framesPerPresent; i++) {
			swiWaitForVBlank();
			if (i == 0) {
				gs_update_sprites(); /* right after the vertical blank, where the sprite table can be copied */
				gs_update_labels();
			}
		}

		/* A script asked for another scene: it is shown from the next frame on. */
		if (gs_pending_scene >= 0) {
			const int next = gs_pending_scene;
			gs_pending_scene = -1;
			if (next < gs_scene_table_count) enter_scene(next, 0);
		}
	}

	return 0;
}
